import { z } from 'zod';
import type { DataCrossCheck } from '../data/game-data';

/**
 * Each province's starting population (F06), `data/province_start.json`.
 * Generated by `npm run import:starting-data`: every country's population
 * (`data/country_start.json`) shared among its provinces in proportion to the
 * people a gridded world population dataset counts in them
 * (`packages/tools/starting-data/`); never edit the output by hand.
 */
export const provinceStartFileSchema = z.strictObject({
  /** The year the numbers describe: the campaign's first year. */
  year: z.int().min(2000).max(2100),
  /** The dataset that says where in each country people live. */
  source: z.strictObject({
    title: z.string().min(1),
    url: z.string(),
    licence: z.string(),
    edition: z.string(),
  }),
  provinces: z.array(
    z.strictObject({
      id: z.string(),
      /** People living in the province. A few tiny island provinces have nobody. */
      population: z.int().min(0),
    }),
  ),
});

export type ProvinceStartFile = z.infer<typeof provinceStartFileSchema>;

/**
 * Cross-file checks: exactly one entry for every province, and each
 * country's provinces add up to the country's population.
 */
export const checkProvinceStart: DataCrossCheck = (data, report) => {
  const file = 'province_start.json';
  const start = data.provinceStart;
  const issue = (path: string, message: string) => report({ file, path, message });
  if (start.year !== data.gameConfig.startDate.year)
    issue(
      'year',
      `the starting data is for ${start.year}, but the campaign starts in ${data.gameConfig.startDate.year} (game_config.json)`,
    );
  const countryOf = new Map(data.provinces.provinces.map((p) => [p.id, p.country]));
  const seen = new Set<string>();
  const totals = new Map<string, number>();
  start.provinces.forEach((p, index) => {
    const country = countryOf.get(p.id);
    if (country === undefined)
      issue(`provinces.${index}.id`, `unknown province "${p.id}" (not in provinces.json)`);
    else if (seen.has(p.id)) issue(`provinces.${index}.id`, `duplicate province "${p.id}"`);
    else totals.set(country, (totals.get(country) ?? 0) + p.population);
    seen.add(p.id);
  });
  for (const p of data.provinces.provinces)
    if (!seen.has(p.id))
      issue(
        'provinces',
        `no starting population for province "${p.id}": run \`npm run import:starting-data\``,
      );
  for (const c of data.countryStart.countries) {
    const total = totals.get(c.id) ?? 0;
    if (total !== c.population)
      issue(
        'provinces',
        `the provinces of "${c.id}" hold ${total} people, but the country has ${c.population} (country_start.json): run \`npm run import:starting-data\``,
      );
  }
};
